const e = $input.first().json || {};
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const ex = e.execution || {};
const msg = String((ex.error && ex.error.message) || 'unknown error').replace(/\s+/g, ' ').slice(0, 300);
const lines = [
  'n8n workflow error',
  'Workflow: ' + wf,
  'Node: ' + (ex.lastNodeExecuted || 'unknown'),
  'Error: ' + msg,
  'Execution: ' + (ex.id || 'n/a'),
];
if (ex.url) lines.push('Open: ' + ex.url);
return [{ json: { text: lines.join('\n'), workflow: wf, node: ex.lastNodeExecuted || '', error: msg } }];
